<script>
var log = [];
function say(k, v) { log.push(k + ' = ' + v); }
var f = document.getElementById('f');
f.addEventListener('load', function () {
  var d = f.contentDocument, w = f.contentWindow;
  var $ = function (id) { return d.getElementById(id); };
  var rows = function () { return d.querySelectorAll('#incident-body tr'); };
  var fire = function (node, type) { node.dispatchEvent(new w.Event(type, { bubbles: true })); };

  say('metrics', d.querySelectorAll('.metric').length);
  say('sparklines', d.querySelectorAll('.metric__spark polyline').length);
  say('bars', d.querySelectorAll('.chart__bar').length);
  say('peakBars', d.querySelectorAll('.chart__bar--peak').length);
  say('rows', rows().length);
  say('firstRowId', rows()[0].getAttribute('data-id'));
  say('firstRowSel', rows()[0].getAttribute('aria-selected'));
  say('ageCell0', rows()[0].querySelector('.col-age').textContent);
  say('pill', $('system-pill-text').textContent);
  say('railCount', $('rail-open-count').textContent);
  say('detailTitle', d.querySelector('.detail__title') ? d.querySelector('.detail__title').textContent : 'NONE');
  say('detailSignals', d.querySelectorAll('.signal').length);
  say('timeline', d.querySelectorAll('.timeline__item').length);
  say('count0', $('result-count').textContent);
  say('services', $('f-service').options.length);

  /* sort by severity toggle */
  d.querySelector('.th-sort[data-sort="severity"]').click();
  say('afterSeverityToggle', Array.prototype.map.call(rows(), function (r) { return r.getAttribute('data-id'); }).join(','));
  d.querySelector('.th-sort[data-sort="age"]').click();
  say('afterAgeSort', Array.prototype.map.call(rows(), function (r) { return r.querySelector('.col-age').textContent; }).join(','));

  /* filter: critical only */
  $('f-severity').value = 'critical'; fire($('f-severity'), 'change');
  say('criticalRows', rows().length);
  say('countFiltered', $('result-count').textContent);

  /* filter to nothing -> empty state */
  $('search').value = 'zzzz'; fire($('search'), 'input');
  say('emptyHidden', $('table-empty').hidden);
  say('tableHidden', $('incident-table').hidden);
  setTimeout(function () {
    say('emptyHiddenAfterDebounce', $('table-empty').hidden);
    say('detailEmpty', !!d.querySelector('#detail-body .empty'));

    /* clear filters */
    $('f-clear').click();
    say('rowsAfterClear', rows().length);

    /* unassigned chip */
    $('f-unassigned').click();
    say('unassignedRows', rows().length + ':' + (rows()[0] ? rows()[0].getAttribute('data-id') : '-'));
    say('chipPressed', $('f-unassigned').getAttribute('aria-pressed'));
    $('f-clear').click();

    /* acknowledge from row button */
    say('ackBtn0', rows()[0].querySelector('[data-ack]').textContent);
    rows()[0].querySelector('[data-ack]').click();
    say('ackAfterRow0Status', rows()[0].querySelector('.col-status').textContent.trim());
    say('ackAfterRow0Btn', rows()[0].querySelector('[data-ack]').textContent + '/disabled=' + rows()[0].querySelector('[data-ack]').disabled);
    say('ackAfterPill', $('system-pill-text').textContent);
    say('ackAfterRail', $('rail-open-count').textContent);
    say('toast', d.querySelectorAll('.toast').length);
    say('detailAckBtn', d.querySelector('#detail-body [data-ack]').textContent + '/disabled=' + d.querySelector('#detail-body [data-ack]').disabled);

    /* keyboard: focus row, arrow down, 'a' acknowledge */
    var r0 = rows()[0];
    r0.focus();
    var ev = function (key) {
      var e = new w.KeyboardEvent('keydown', { key: key, bubbles: true, cancelable: true });
      d.activeElement.dispatchEvent(e);
    };
    ev('ArrowDown');
    say('focusAfterArrow', d.activeElement.getAttribute('data-id'));
    ev('a');
    say('kbdAckStatus', d.activeElement.querySelector('.col-status').textContent.trim());

    /* select a different row by click */
    var target = rows()[3] || rows()[1];
    target.click();
    say('selectedAfterClick', d.querySelector('#incident-body tr.is-selected').getAttribute('data-id'));
    say('ownerCell', target.querySelector('.col-owner').textContent.trim());

    /* assign to me */
    d.querySelector('#detail-body [data-assign]').click();
    say('ownerAfterAssign', d.querySelector('#detail-body .kv dd.is-text').textContent);

    /* overflow / layout checks at desktop width */
    say('docScrollW', d.documentElement.scrollWidth);
    say('docClientW', d.documentElement.clientWidth);
    say('tableWrapOverflow', d.querySelector('.table-wrap').scrollWidth + '/' + d.querySelector('.table-wrap').clientWidth);

    /* mobile */
    f.width = 390; f.height = 1400;
    setTimeout(function () {
